<?php require 'faculty_bootstrap.php';$title='My Classes';$fid=(int)$_SESSION['user']['id'];$selected=(int)($_GET['offering']??0);
$q=$pdo->prepare("SELECT o.*,s.code,s.name,s.units,s.description,s.prerequisite,COUNT(DISTINCT CASE WHEN e.status='approved' THEN e.student_id END) student_count FROM subject_offerings o JOIN subjects s ON s.id=o.subject_id LEFT JOIN enrollments e ON e.offering_id=o.id WHERE o.faculty_id=? GROUP BY o.id ORDER BY s.code,o.section");$q->execute([$fid]);$classes=$q->fetchAll();
$grouped=[]; foreach($classes as $c){ $key=$c['subject_id']; if(!isset($grouped[$key])){ $grouped[$key]=['code'=>$c['code'],'name'=>$c['name'],'units'=>$c['units'],'offerings'=>[]]; } $grouped[$key]['offerings'][]=$c; } $grouped=array_values($grouped);
$detail=null;$roster=[];if($selected){$q=$pdo->prepare("SELECT o.*,s.code,s.name,s.units,s.description,s.prerequisite FROM subject_offerings o JOIN subjects s ON s.id=o.subject_id WHERE o.id=? AND o.faculty_id=?");$q->execute([$selected,$fid]);$detail=$q->fetch();if($detail){$r=$pdo->prepare("SELECT DISTINCT u.id,u.name,u.student_id,u.email,u.program,e.status,e.created_at FROM enrollments e JOIN users u ON u.id=e.student_id WHERE e.offering_id=? AND e.status='approved' ORDER BY u.name");$r->execute([$selected]);$roster=$r->fetchAll();}}
require 'header.php';faculty_flash_html();
?><section class="section"><div class="section-intro"><div><span class="eyebrow">TEACHING</span><h2>My Classes</h2><p class="muted">Classes assigned to <?=e($_SESSION['user']['name'])?>.</p></div><a class="btn subtle-btn" href="faculty_schedule.php">Teaching Schedule</a></div><?php if(!$classes):?><p class="muted">No classes are currently assigned to you.</p><?php endif;?><?php foreach($grouped as $g):?><div class="faculty-class-group"><div class="faculty-class-group-head"><div><span class="eyebrow"><?=e($g['code'])?></span><h3><?=e($g['name'])?></h3><p><?=e($g['units'])?> units · <?=count($g['offerings'])?> section<?=count($g['offerings'])===1?'':'s'?></p></div></div><?php foreach($g['offerings'] as $c):?><a class="faculty-class-card <?=($selected===$c['id']?'selected':'')?>" href="faculty_classes.php?offering=<?=$c['id']?>"><div><b>Section <?=e($c['section'])?></b></div><div><b><?=e($c['day_name'])?></b><span><?=date('g:i A',strtotime($c['start_time']))?>–<?=date('g:i A',strtotime($c['end_time']))?></span><span><?=e($c['room'])?></span></div><div class="faculty-class-count"><strong><?=e($c['student_count'])?></strong><small>Students</small></div></a><?php endforeach;?></div><?php endforeach;?></section>
<?php if($detail):?><section class="section"><div class="card-head"><div><span class="eyebrow">CLASS DETAILS</span><h2><?=e($detail['code'])?> — <?=e($detail['name'])?></h2><p class="muted"><?=e($detail['day_name'])?> · <?=date('g:i A',strtotime($detail['start_time']))?>–<?=date('g:i A',strtotime($detail['end_time']))?> · <?=e($detail['room'])?> · Section <?=e($detail['section'])?></p></div><a class="small-link" href="faculty_students.php?offering=<?=e($detail['id'])?>">Open student list →</a></div><div class="subject-detail-grid"><div><span>Units</span><p><?=e($detail['units'])?></p></div><div><span>Prerequisite</span><p><?=e($detail['prerequisite']?:'None')?></p></div><div><span>Description</span><p><?=e($detail['description']?:'No description available.')?></p></div><div><span>Students</span><p><?=e(count($roster))?> currently enrolled</p></div></div><h3 class="subsection-title">Enrolled Students</h3><div class="table-scroll"><table class="table"><tr><th>Student</th><th>Student ID</th><th>Program</th><th>Email</th></tr><?php foreach($roster as $r):?><tr><td><b><?=e($r['name'])?></b></td><td><?=e($r['student_id']?:'—')?></td><td><?=e($r['program']?:'—')?></td><td><?=e($r['email'])?></td></tr><?php endforeach;?></table></div></section><?php endif;?><?php require 'footer.php';?>
